# Writes testdata/arith.lua: every binary operator applied to every pair of a set of tricky
# operands, once from two locals and once with a constant right operand, and the unary
# operators on each operand. go test -update fills in C Lua's results.
values = [
    "0", "1", "-1", "3", "-3", "7", "2", "64", "-64", "63",
    "9223372036854775807", "(-9223372036854775807 - 1)", "9007199254740993",
    "0.0", "(-0.0)", "0.5", "-0.5", "3.5", "-3.5", "2^53", "1e308", "1/0", "-1/0", "0/0",
    "'10'", "'0x10'", "'3.5'", "'abc'",
]
binops = ["+", "-", "*", "/", "%", "//", "^", "&", "|", "~", "<<", ">>", "==", "<", "<=", ">", ">="]
out = ["-- Generated by testdata/gen/arith.py. Each case is one operation."]
n = 0
for op in binops:
    for a in values:
        for b in values:
            n += 1
            out.append(f"--== {n} {a} {op} {b}")
            out.append(f"local a, b = {a}, {b} return a {op} b")
            if not b.startswith("("):
                n += 1
                out.append(f"--== {n} {a} {op} K{b}")
                out.append(f"local a = {a} return a {op} {b}")
for op in ["-", "~", "not "]:
    for a in values:
        n += 1
        out.append(f"--== {n} {op}{a}")
        out.append(f"local a = {a} return {op}a")
open("testdata/arith.lua", "w").write("\n".join(out) + "\n")
print(n, "cases")
